import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Sweeps over the predicate domain serve older snapshots too, so the domain must keep a predicate whose later commits
 * cancel out.
 */
class LmdbAdjacencyPredicateDomainTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final IRI S = F.createIRI("http://example.org/domain/s");
	private static final IRI P = F.createIRI("http://example.org/domain/p");
	private static final IRI Q = F.createIRI("http://example.org/domain/q");
	private static final IRI O = F.createIRI("http://example.org/domain/o");
	private static final IRI G = F.createIRI("http://example.org/domain/g");

	@TempDir
	File dataDir;

	private SailRepository repo;

	@AfterEach
	void tearDown() {
		if (repo != null) {
			repo.shutDown();
		}
	}

	@Test
	void aSnapshotBetweenAPredicatesAddAndItsRemovalStillSeesItsRows() throws Exception {
		LmdbStore sail = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repo = new SailRepository(sail);
		repo.init();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.add(S, P, O, G);
		}
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.add(S, Q, O, G);
		}

		try (RepositoryConnection reader = repo.getConnection()) {
			reader.begin(IsolationLevels.SNAPSHOT);
			// Pin the snapshot that holds both statements.
			assertThat(statements(reader)).hasSize(2);
			try (RepositoryConnection writer = repo.getConnection()) {
				// q's only statement goes away again: its net change since the base is zero.
				writer.remove(S, Q, O, G);
			}
			assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();

			assertThat(count(reader, "SELECT (COUNT(*) AS ?c) WHERE { GRAPH <" + G + "> { ?s ?p ?o } }"))
					.as("the pinned snapshot's graph %s", sail.getDirectAdjacencyReadinessDescription())
					.isEqualTo(2);
			assertThat(count(reader, "SELECT (COUNT(*) AS ?c) WHERE { ?s ?p ?o }")).isEqualTo(2);
			assertThat(statements(reader)).hasSize(2);
			reader.commit();
		}
	}

	@Test
	void aViewAcquiredLateForAnOlderSnapshotStillCountsTheCancelledPredicate() throws Exception {
		LmdbStore sail = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repo = new SailRepository(sail);
		repo.init();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.add(S, P, O, G);
		}
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		LmdbSailStore backing = sail.getBackingStore();
		LmdbDirectAdjacencyStore direct = backing.directAdjacencyStore();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.add(S, Q, O, G);
		}
		long bothPresent = backing.getTripleStore().getDataRevision();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.remove(S, Q, O, G);
		}
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		long graph = backing.valueStore().getId(G);

		// A parallel query sibling acquires lazily with its parent's revision, after the removal was published.
		try (LmdbAdjacencyReadView view = direct.acquire(bothPresent)) {
			assertThat(view.servesSnapshot()).as(sail.getDirectAdjacencyReadinessDescription()).isTrue();
			assertThat(direct.tryCount(view, -1, -1, -1, graph, true)).as("statements in the graph at revision %d",
					bothPresent).isEqualTo(2);
		}
	}

	private static Set<Statement> statements(RepositoryConnection connection) {
		Set<Statement> statements = new HashSet<>();
		try (RepositoryResult<Statement> result = connection.getStatements(null, null, null, false)) {
			result.forEach(statements::add);
		}
		return statements;
	}

	private static int count(RepositoryConnection connection, String query) {
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			BindingSet bindings = result.next();
			return ((Literal) bindings.getValue("c")).intValue();
		}
	}
}
